(function ($) {
  function gamipress_learndash_points_gateway_update_checkout() {
    var payment_method = $(
      "#payment.learndash-checkout-payment input.input-radio:checked",
    ).val();
    if (
      payment_method !== undefined &&
      payment_method.startsWith("gamipress_")
    ) {
      var points_type = payment_method.replace("gamipress_", "");
      $("#order_review .gamipress-learndash-points-gateway-active")
        .removeClass("gamipress-learndash-points-gateway-active")
        .hide();
      $(
        "#order_review #payment-method-gamipress-" +
          points_type +
          "-user-balance-wrap",
      )
        .addClass("gamipress-learndash-points-gateway-active")
        .show();
      $(
        "#order_review #payment-method-gamipress-" +
          points_type +
          "-required-balance-wrap",
      )
        .addClass("gamipress-learndash-points-gateway-active")
        .show();
      $(
        "#order_review #payment-method-gamipress-" +
          points_type +
          "-new-balance-wrap",
      )
        .addClass("gamipress-learndash-points-gateway-active")
        .show();
    } else {
      $("#order_review .gamipress-learndash-points-gateway-active")
        .removeClass("gamipress-learndash-points-gateway-active")
        .hide();
    }
  }
  $("body").on(
    "change",
    "#payment.learndash-checkout-payment input.input-radio",
    function () {
      gamipress_learndash_points_gateway_update_checkout();
    },
  );
  if ($("#payment.learndash-checkout-payment input.input-radio:checked").length)
    gamipress_learndash_points_gateway_update_checkout();
  $("body").on("updated_checkout", function () {
    gamipress_learndash_points_gateway_update_checkout();
  });
})(jQuery);
